 import { gsap } from 'gsap';
import {
  MeshBasicNodeMaterial,
  Mesh,
  PlaneGeometry,
  Group,
  Color,
  DoubleSide
} from 'three/webgpu';

export default function createNode(config, ctx) {
  const group = new Group();

  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const spec = config.intent?.visualSpec ?? {};
  const colors = spec.colors ?? config.colors ?? {
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    surface: '#0b0b10'
  };

  const width = 2.0;
  const height = 1.25;
  const thickness = 0.03;

  const cardGeo = new PlaneGeometry(width, height);
  const cardMat = new MeshBasicNodeMaterial({
    color: new Color(colors.surface),
    transparent: true,
    side: DoubleSide
  });
  const card = new Mesh(cardGeo, cardMat);
  card.userData.isHitTarget = true;
  group.add(card);

  let disposed = false;
  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      if (disposed) return;
      cardMat.map = tex;
      cardMat.color.set(colors.paper);
      cardMat.needsUpdate = true;
    }).catch(() => {});
  }

  const edgeMat = new MeshBasicNodeMaterial({
    color: new Color(colors.accent),
    transparent: true,
    opacity: 0,
    side: DoubleSide
  });

  const topGeo = new PlaneGeometry(width + thickness * 2, thickness);
  const bottomGeo = new PlaneGeometry(width + thickness * 2, thickness);
  const leftGeo = new PlaneGeometry(thickness, height);
  const rightGeo = new PlaneGeometry(thickness, height);

  const top = new Mesh(topGeo, edgeMat);
  top.position.set(0, height / 2 + thickness / 2, 0.006);
  const bottom = new Mesh(bottomGeo, edgeMat);
  bottom.position.set(0, -height / 2 - thickness / 2, 0.006);
  const left = new Mesh(leftGeo, edgeMat);
  left.position.set(-width / 2 - thickness / 2, 0, 0.006);
  const right = new Mesh(rightGeo, edgeMat);
  right.position.set(width / 2 + thickness / 2, 0, 0.006);

  group.add(top, bottom, left, right);

  const hero = items.find((i) => i.role === 'headline') || items[0];
  const label = typeof hero?.text === 'string' ? hero.text : 'Journal 3';
  const fontSize = typeof hero?.typography?.fontSize === 'number'
    ? hero.typography.fontSize / 200
    : 0.2;

  const labelObj = ctx.fontAtlas.createText(label, {
    fontSize,
    color: colors.paper,
    align: 'center'
  });
  labelObj.position.set(0, 0, 0.03);
  group.add(labelObj);

  let hoverTween, edgeTween, pressTween;
  let isPressed = false;

  const clearMotion = () => {
    gsap.killTweensOf(group.position);
    gsap.killTweensOf(group.scale);
    gsap.killTweensOf(edgeMat);
    if (hoverTween) { hoverTween.kill(); hoverTween = null; }
    if (edgeTween) { edgeTween.kill(); edgeTween = null; }
    if (pressTween) { pressTween.kill(); pressTween = null; }
  };

  const riseIn = () => {
    clearMotion();
    hoverTween = gsap.to(group.position, {
      y: 0.15,
      duration: 0.35,
      ease: 'power2.out'
    });
    edgeTween = gsap.to(edgeMat, {
      opacity: 0.8,
      duration: 0.3,
      ease: 'power2.out'
    });
  };

  const settleBack = () => {
    clearMotion();
    hoverTween = gsap.to(group.position, {
      y: 0,
      duration: 0.35,
      ease: 'power2.out'
    });
    edgeTween = gsap.to(edgeMat, {
      opacity: 0,
      duration: 0.3,
      ease: 'power2.out'
    });
    if (isPressed) releasePress();
  };

  const pressDown = () => {
    isPressed = true;
    clearMotion();
    pressTween = gsap.to(group.scale, {
      x: 0.97,
      y: 0.97,
      z: 0.97,
      duration: 0.12,
      ease: 'back.out'
    });
  };

  const releasePress = () => {
    isPressed = false;
    clearMotion();
    pressTween = gsap.to(group.scale, {
      x: 1,
      y: 1,
      z: 1,
      duration: 0.15,
      ease: 'power2.out'
    });
  };

  const onClick = () => {
    ctx.emit('hub-journal.select', { id: config.id });
  };

  group.userData.isInteractive = true;
  group.userData.handlers = {
    hover: riseIn,
    pointerenter: riseIn,
    pointerleave: settleBack,
    pointerdown: pressDown,
    pointerup: releasePress,
    click: onClick
  };

  group.userData.cleanup = () => {
    disposed = true;
    clearMotion();
    cardMat.map?.dispose();
    cardGeo.dispose();
    topGeo.dispose();
    bottomGeo.dispose();
    leftGeo.dispose();
    rightGeo.dispose();
    cardMat.dispose();
    edgeMat.dispose();
    group.remove(card);
    group.remove(labelObj);
    group.traverse((o) => {
      if (o.isMesh) {
        o.geometry?.dispose();
        if (Array.isArray(o.material)) {
          o.material.forEach((m) => m.dispose());
        } else {
          o.material?.dispose();
        }
      }
    });
  };

  return group;
}
